/// An Engram row read that failed on this rank alone (a disk or memory fault; the peer's own read went through) leaves
/// this rank without its part of the layer's allGather while the peer waits in it, so the ranks cannot go on together:
/// the error becomes EngramRankFault, which ends the pair (round.pair_ending) instead of failing one request. It is
/// applied where a read's error is made or stored (engramRows, the read-ahead, TF_DS_ENGRAM_LEAD's reader). Any other
/// error passes through unchanged.
pub fn rankFault(err: anyerror) anyerror {
    switch (err) {
        error.ReadFailed, error.EndOfFile, error.OutOfMemory, error.RowOutOfRange => {
            std.log.warn("dsv41: an Engram row read failed on this rank ({s}); the ranks end", .{@errorName(err)});
            return error.EngramRankFault;
        },
        else => return err,
    }
}

/// Layer slot l's decoded rows of chunk [start, start + n) (engramApply's host part): read ahead if ready, else here.
pub fn engramRows(eh: *EngramHost, l: usize, t: engram_io.Table, seq: []const i32, start: usize, n: usize) ![]u16 {
    const cols = eh.hasher.cols();
    const k = eh.hi - eh.lo;
    const m = n * k;
    const lead = eh.lead_on and l < 2;
    if (lead) {
        if (eh.lead_ready[l] and eh.lead_start[l] == start and eh.lead_n[l] == n) {
            eh.lead_ready[l] = false;
            return eh.ahead_rows[l];
        }
    } else if (l < 2 and eh.ahead_ready[l] and eh.ahead_start == start and eh.ahead_n == n) {
        eh.ahead_ready[l] = false;
        return eh.ahead_rows[l];
    }
    eh.hashesFor(seq, start, n);
    for (0..n) |r| {
        for (0..k) |j| eh.flat[r * k + j] = eh.hashes[(r * eh.hasher.layers + l) * cols + eh.lo + j];
    }
    // (TF_DS_ENGRAM_LEAD: on this layer's ring, its reader joined; the other layer's may be reading on its own)
    const ring = if (lead) eh.lead_ring[l] else eh.paio;
    const timed = eh.metrics;
    const t0 = if (timed) readStamp(eh) else 0;
    const read = engramReadRows(eh, ring, t, eh.flat[0..m], eh.w[0 .. m * t.row_w], eh.s[0 .. m * t.row_s], true);
    if (timed) eh.reads.observe(readStamp(eh) - t0);
    read catch |err| return rankFault(err);
    eh.decode(eh.w[0 .. m * t.row_w], eh.s[0 .. m * t.row_s], eh.rows[0 .. m * t.row_w], m, t.row_w, t.row_s); // the rows on the decode threads
    return eh.rows[0 .. m * t.row_w];
}

/// Layer li's Engram on the chunk (engram_apply, no image span), as _forward_k runs it before the attention mixes: a
/// pending MoE post into the streams first (hc_post), then the rows of each position's n-grams (hashed on the host from
/// `seq`, the whole sequence's ids so far; read from the tables; decoded to bf16 as Engram._decode does), their
/// projection summed over the ranks in rank order, rounded to bf16, and the gate into the streams.
pub fn engramApply(e: *const Engine, ch: *Chunk, eh: *EngramHost, li: usize, seq: []const i32) !void {
    const lay = e.w.layers[li];
    const ew = lay.engram_wkv orelse return;
    const c = e.c;
    const n = ch.n;
    // TF_DS_PREFILL_GATHER_OVERLAP: with the layer's gather still in flight on the side stream, the pending post waits
    // until the rows are read and uploaded, so the gather overlaps them; with nothing in flight it stays the first step.
    const late = ch.pending_side and ch.pending;
    if (!late) try pendingPost(e, ch);
    const li32: u16 = @intCast(li);
    const l = std.mem.indexOfScalar(u16, c.engram_layers.slice(), li32) orelse return error.NotAnEngramLayer;
    const t = eh.tables.layers.get(@intCast(li)) orelse return error.MissingEngramTable;
    const k = eh.hi - eh.lo;
    const m = n * k;
    const prof = eh.profile;
    var tq = if (prof) pstamp(e, eh) else 0;
    // the rows read ahead (fillChunk's thread) when they are this chunk's, else read here
    const rows = try engramRows(eh, l, t, seq, ch.start, n);
    if (m * t.row_w != n * ew.k) return error.EngramShape;
    if (prof) eh.p_rows += lap(e, eh, &tq);
    try upload(e, ch.eb, rows.ptr, m * t.row_w * 2);
    if (prof) eh.p_upload += lap(e, eh, &tq);
    if (late) try pendingPost(e, ch);
    try mm(e, ch, ew, ch.eb, ew.k, ch.ek, .fp32, ew.n);
    if (prof) eh.p_mm += lap(e, eh, &tq);
    // 2D (model.py esum): this node's columns of its rank's projection; the quarters give both ranks' whole ones
    const en = if (e.two) |two| two.engramWidth() else ew.n;
    // 2D chunks past the rings: the pair's sum then the pairs' bf16 halves (Two.engramSum), the same bits
    const psum = if (e.two) |two| two.rings == null or n >= 64 else false;
    if (psum) {
        try e.two.?.engramSum(e, ch.ek, ch.ekg, ch.kv, n);
        if (prof) eh.p_x += lap(e, eh, &tq);
    } else {
        if (e.two) |two| try two.quarters(e, ch.ek, ch.ekg, n, two.ew, 4) else try e.comm.allGather(ch.ek, ch.ekg, n * ew.n, .f32, e.s);
        if (prof) eh.p_x += lap(e, eh, &tq);
        if (e.world != 2) return notPorted(@src()); // Comm.sum of more ranks: acc += g[r]
        try e.ops.add2Bf16(e.s, ch.ekg, ch.ekg + n * en * 4, ch.kv, n * en);
    }
    try tri_basic.engramGate(e.t, ch.h, ch.kv, lay.engram_qk, ch.h_alt, c.eps, n, c.hidden);
    swapStreams(ch, ch.h_alt);
    // image spans take no Engram contribution: their rows keep the streams they came with (engram_mask)
    const rowb = c.hc * c.hidden * 2;
    for (ch.spans) |sp| {
        const o = overlap(sp, ch.start, n) orelse continue;
        try e.ops.copyRows(e.s, ch.h_alt + o[0] * rowb, rowb, ch.h + o[0] * rowb, rowb, rowb, o[1] - o[0]);
    }
    if (prof) {
        eh.p_gate += lap(e, eh, &tq);
        eh.p_calls += 1;
    }
}

/// A profile's clock after the stream drains (prompt Engram split).
fn pstamp(e: *const Engine, eh: *const EngramHost) u64 {
    e.s.synchronize() catch {};
    return @intCast(std.Io.Timestamp.now(eh.io.?, .awake).nanoseconds);
}

fn lap(e: *const Engine, eh: *const EngramHost, t: *u64) u64 {
    const now = pstamp(e, eh);
    defer t.* = now;
    return now - t.*;
}

/// A chunk's rows `ids` of table `t` by AIO (the pool's bytes, at ~0.07 s for 24,576 rows where the pool's preads take
/// ~0.5 s on one GB10): batches of a quarter of the ring's slots (two reads a row), all submitted (a submit reaps while the
/// ring is full), then waited for in order.
pub fn aioGather(aio: *engram_aio.Aio, t: engram_io.Table, ids: []const i64, out_w: []u8, out_s: []u8) !void {
    const def = @max(aio.slots / 4, 1);
    const per = if (aio.batch) |b| @min(def, b) else def; // TF_DS_ENGRAM_AIO_BATCH: an upper bound on a batch's rows
    var batch: [64]u64 = undefined;
    var first: usize = 0;
    var pending: usize = 0;
    errdefer for (0..pending) |i| aio.wait(batch[(first + i) % batch.len]) catch {};
    var at: usize = 0;
    while (at < ids.len) : (at += per) {
        if (pending == batch.len) {
            const oldest = batch[first];
            first = (first + 1) % batch.len;
            pending -= 1;
            try aio.wait(oldest);
        }
        const n = @min(per, ids.len - at);
        batch[(first + pending) % batch.len] = try aio.start(t, ids[at..][0..n], out_w[at * t.row_w ..][0 .. n * t.row_w], out_s[at * t.row_s ..][0 .. n * t.row_s]);
        pending += 1;
    }
    while (pending != 0) {
        const oldest = batch[first];
        first = (first + 1) % batch.len;
        pending -= 1;
        try aio.wait(oldest);
    }
}

/// The rows of one block of the indexer's scores for a chunk of `n` rows over `n_comp_end` compressed keys: as many as
/// keep the [rows, n_comp] keys within 2^26 / 4 elements, a multiple of 16 unless one block holds the whole chunk, so
/// every later block's views (vis + r0 * 8 and the rest) start on a 16-byte boundary, the alignment the kit's index
/// kernels were captured for (137,612 compressed keys gave 121-row blocks: MissingTritonVariant at the second). A row's
/// scores and picks are its own, so the block size changes no bits.
fn indexRowBlock(n: usize, n_comp_end: usize) usize {
    return @max(16, @min(n, (@as(usize, 1) << 26) / (4 * @max(n_comp_end, 1)) / 16 * 16));

/// A prompt chunk's buffers for up to `cap` rows (model.py _forward_k's and its steps' torch.empty's).
/// An image span of the prompt: positions [at, at + len), its rows from row `row` of the image rows buffer.
pub const Span = struct { at: usize, len: usize, row: usize };

/// TF_DS_EXACT_RESUME (Model.tails): a slot's last `window` rows of a prompt pass's decoder input, a ring by position
/// (the row at position p at slot p % window), h then pre: the rows a resumed pass replays from before its start.
pub const Tail = struct {
    buf: u64 = 0, // bf16 [window, hc, D] then fp32 [window, hc]
    start: usize = 0, // the positions the ring holds, [start, end) (0 and 0: none)
    end: usize = 0,
    resume_at: usize = 0, // where the pass resumes (0: from the start): only its first chunk takes rows from the tail
};

/// TF_DS_EXACT_RESUME: the rows a pass takes from its tail before its start (replayCut's prepend), 0 for none: the
/// pass's first chunk (start == the resume point) whose replay reaches before it, the tail holding [replay, start).
/// error.TailUncovered: the tail does not hold them.
pub fn tailPre(ch_start: usize, replay: usize, t: *const Tail) !usize {
    if (ch_start != t.resume_at or replay >= ch_start) return 0;
    if (replay < t.start or ch_start > t.end) return error.TailUncovered;
    return ch_start - replay;
}

/// TF_DS_EXACT_RESUME: the tail rows a chunk adds, [lo, hi): its rows in the pass's last `window` positions.
pub fn tailRows(ch_start: usize, ch_n: usize, replay: usize, window: usize) [2]usize {
    const hi = @min(ch_start + ch_n, replay + window);
    return .{ @max(ch_start, hi -| window), hi };
}

test "a tail's prepend and its rows: the pass's first chunk takes [replay, start) from the ring, a later chunk none" {
    // a previous pass ending at 10,000: the ring holds [9,872, 10,000)
    var t: Tail = .{ .start = 10_000 - 128, .end = 10_000, .resume_at = 10_000 };
    try std.testing.expectEqual(@as(usize, 100), try tailPre(10_000, 10_000 - 128 + 28, &t)); // 128 - 28 rows before the resume
    try std.testing.expectEqual(@as(usize, 0), try tailPre(10_000, 10_000, &t)); // replay at the start: nothing to prepend
    try std.testing.expectEqual(@as(usize, 1), try tailPre(10_000, 9_999, &t)); // a row before it comes from the ring
    t.resume_at = 8_192; // a later chunk: its start is not the resume point
    try std.testing.expectEqual(@as(usize, 0), try tailPre(10_240, 10_000, &t));
    // the ring's rows a chunk adds: the last `window` positions of the pass, never more
    try std.testing.expectEqual([2]usize{ 10_000, 10_128 }, tailRows(9_000, 1_128, 10_000, 128));
    try std.testing.expectEqual([2]usize{ 10_000, 10_050 }, tailRows(10_000, 50, 10_000, 128));
    // a tail that does not hold the replay is refused (the prompt was shorter than the window)
    var short: Tail = .{ .start = 0, .end = 100, .resume_at = 100 };
    try std.testing.expectEqual(@as(usize, 100), try tailPre(100, 0, &short)); // the whole state, its prompt shorter than the window
    try std.testing.expectError(error.TailUncovered, tailPre(100, 0, &.{ .start = 40, .end = 100, .resume_at = 100 }));
}

test "TF_DS_EXACT_RESUME: a pass's tail across chunks, its turn's deltas, and the prepend a cold pass's rows take" {
    const window = 128;
    const Ring = struct {
        const none = std.math.maxInt(usize);
        /// The pass's chunks (2048 rows, the last shorter) stashed into the ring: slot -> the position it holds.
        fn stash(ring: []usize, len: usize, window_: usize, chunks: []const usize) void {
            @memset(ring, none);
            var start: usize = 0;
            var i: usize = 0;
            while (start < len) : (i += 1) {
                const n = @min(if (i < chunks.len) chunks[i] else 2048, len - start);
                const r = tailRows(start, n, len -| window_, window_);
                for (r[0]..r[1]) |p| ring[p % window_] = p;
                start += n;
            }
        }
        /// The ring holds exactly the positions [lo, hi) (each at its slot).
        fn holds(ring: []const usize, lo: usize, hi: usize, window_: usize) bool {
            for (lo..hi) |p| if (ring[p % window_] != p) return false;
            return true;
        }
    };
    var ring: [window]usize = undefined;
    // a cold pass: the whole prompt under the window, the window's last rows at or past it (an exact grid multiple too)
    for ([_]usize{ 1, 127, 128, 129, 2 * 2048, 10_000 }) |len| {
        Ring.stash(&ring, len, window, &.{});
        try std.testing.expect(Ring.holds(&ring, len -| window, len, window));
    }
    // a prompt whose last window's rows span two chunks: both stashed, the ring holds them in position order
    Ring.stash(&ring, 2 * 2048 + 100, window, &.{});
    try std.testing.expect(Ring.holds(&ring, 2 * 2048 + 100 - window, 2 * 2048 + 100, window));
    // a resumed pass re-stashes its own rows over the ones it dropped: the ring holds the last window positions
    Ring.stash(&ring, 10_000, window, &.{});
    const st: Tail = .{ .start = 10_000 - window, .end = 10_000, .resume_at = 10_000 };
    const r2 = tailRows(10_000, 50, 10_050 -| window, window);
    for (r2[0]..r2[1]) |p| ring[p % window] = p;
    try std.testing.expect(Ring.holds(&ring, 10_050 -| window, 10_050, window));
    // a turn's deltas: the rows the pass takes from the tail before its state, 0 once the replay is past it
    for ([_]struct { d: usize, pre: usize }{ .{ .d = 1, .pre = 127 }, .{ .d = 127, .pre = 1 }, .{ .d = 128, .pre = 0 }, .{ .d = 129, .pre = 0 }, .{ .d = 2048, .pre = 0 }, .{ .d = 2049, .pre = 0 } }) |c| {
        try std.testing.expectEqual(@as(usize, c.pre), try tailPre(st.resume_at, 10_000 + c.d - window, &st));
    }
    // an odd end is kept one short (a ratio-2 layer refuses an odd start): its tail is the window before that
    Ring.stash(&ring, 10_001, window, &.{});
    const odd: Tail = .{ .start = 10_001 - window, .end = 10_001, .resume_at = 10_000 };
    try std.testing.expectEqual(@as(usize, 126), try tailPre(odd.resume_at, 10_002 - window, &odd));
    // the decoder's input rows: the tail's before the state, the chunk's after it, in the position order a cold pass
    // lays them out (the same rows for the same positions)
    const len2 = 10_001;
    const pre = try tailPre(st.resume_at, len2 - window, &st);
    const replay = len2 - window;
    var got: [window]usize = undefined;
    var i: usize = 0;
    for (replay..st.resume_at) |p| {
        got[i] = ring[p % window];
        i += 1;
    }
    for (st.resume_at..len2) |p| {
        got[i] = p;
        i += 1;
    }
    try std.testing.expectEqual(window, i);
    try std.testing.expectEqual(@as(usize, 127), pre);
    for (got[0..i], 0..i) |g, j| try std.testing.expectEqual(replay + j, g);
}

/// The rows [r0, r1) of the chunk (relative to its start) a span covers, if any.
fn overlap(sp: Span, start: usize, n: usize) ?[2]usize {
    const lo = @max(sp.at, start);
    const hi = @min(sp.at + sp.len, start + n);
    return if (lo < hi) .{ lo - start, hi - start } else null;
}

pub const Chunk = struct {
    cap: usize,
    tail: ?*Tail = null, // TF_DS_EXACT_RESUME: the slot's tail (Model.tails; null: the switch off)
    spans: []const Span = &.{}, // the prompt's image spans (absolute positions)
    img_rows: u64 = 0, // bf16 [span tokens, D]: their rows
    pick_vl: u64 = 0, // int32 [cap, slots]: the routing of span rows with the image bias, before it joins pick
    wts_vl: u64 = 0, // fp32 [cap, slots]
    n: usize = 0,
    start: usize = 0,
    ids: u64, // int64 [cap]
    pos: u64, // int64 [n]: start .. start + n (after a replay cut a view into pos0, pos[first:])
    pos0: u64, // int64 [cap]: the chunk's positions as begin() wrote them
    pos1: u64 = 0, // int64 [cap]: a replay cut's positions moved to a 16-byte boundary (replayCut)

    return @max(16, @min(n, (@as(usize, 1) << 26) / (4 * @max(n_comp_end, 1)) / 16 * 16));
}

/// TF_DS_EXACT_RESUME: `rows` rows of the ring at `ring` from position `p0`, to/from `dst`'s rows at `dst_row` (a row
/// `rb` bytes), in two copies when the ring wraps.
fn tailRowsCopy(e: *const Engine, ring: u64, dst: u64, dst_row: usize, rb: usize, p0: usize, rows: usize, from_ring: bool) !void {
    const slots = e.c.window;
    const slot = p0 % slots;
    const n1 = @min(rows, slots - slot);
    const src = ring + slot * rb;
    const dst1 = dst + dst_row * rb;
    if (from_ring) {
        try e.ops.copyRows(e.s, src, rb, dst1, rb, rb, n1);
        if (rows > n1) try e.ops.copyRows(e.s, ring, rb, dst1 + n1 * rb, rb, rb, rows - n1);
    } else {
        try e.ops.copyRows(e.s, dst1, rb, src, rb, rb, n1);
        if (rows > n1) try e.ops.copyRows(e.s, dst1 + n1 * rb, rb, ring, rb, rb, rows - n1);
    }
}

/// TF_DS_EXACT_RESUME: the tail takes this chunk's decoder input rows of the pass's last `window` positions (replayCut
/// runs before the decoder layers, on the rows they read).
fn tailStash(e: *const Engine, ch: *const Chunk, replay: usize) !void {
    const t = ch.tail orelse return;
    if (t.buf == 0) return;
    const c = e.c;
    const r = tailRows(ch.start, ch.n, replay, c.window);
    if (r[1] <= r[0]) return;
    const row_h = c.hc * c.hidden * 2;
    const row_p = c.hc * 4;
    try tailRowsCopy(e, t.buf, ch.h, r[0] - ch.start, row_h, r[0], r[1] - r[0], false);
    try tailRowsCopy(e, t.buf + c.window * row_h, ch.pre, r[0] - ch.start, row_p, r[0], r[1] - r[0], false);
    t.end = @max(t.end, r[1]);
    t.start = t.end -| c.window;
}

/// The decoder's bounded replay at its first layer (_forward_k's `replay`, CED's prefill): the layer's attention mixes
/// (the pending MoE post fused in) and its kv-source update over every row of the chunk, then the chunk cut to its rows
/// at positions >= replay, the streams and their pre copied down (h[first:], pre[first:]). The decoder layers then run
/// on those rows with no window key before replay and this layer's update done. False: an encoder-only chunk (no
/// row at or past replay), which ends here.
///
/// TF_DS_EXACT_RESUME: a resumed pass whose replay reaches before its start takes the rows [replay, start) from its
/// tail first (the previous pass's decoder input), so the decoder runs on [replay, chunk end) as a cold pass would.
pub fn replayCut(e: *const Engine, ch: *Chunk, cs: *const Caches, sh: *Shared, li: usize, replay: usize, host_pos: []i64) !bool {
    try attnMixes(e, ch, li);
    if (e.w.layers[li].comp_wkv == null) return error.NoKvSource;
    try kvSourceUpdate(e, ch, cs, sh, li);
    const c = e.c;
    const pre = if (ch.tail) |t| try tailPre(ch.start, replay, t) else 0;
    const first = @max(ch.start, replay) - ch.start;
    if (first >= ch.n) return false;
    const n = ch.n - first + pre;
    if (n > ch.cap or (pre > 0 and host_pos.len < n)) return error.ChunkTooLong;
    if (first > 0 or pre > 0) {
        const row_h = c.hc * c.hidden * 2;
        const row_p = c.hc * 4;
        try e.ops.copyRows(e.s, ch.h + first * row_h, row_h, ch.h_alt + pre * row_h, row_h, row_h, ch.n - first);
        if (pre > 0) try tailRowsCopy(e, ch.tail.?.buf, ch.h_alt, 0, row_h, replay, pre, true); // rows [0, pre)
        std.mem.swap(u64, &ch.h, &ch.h_alt);
        try e.ops.copyRows(e.s, ch.pre + first * row_p, row_p, ch.pre_f + pre * row_p, row_p, row_p, ch.n - first);
        if (pre > 0) try tailRowsCopy(e, ch.tail.?.buf + c.window * row_h, ch.pre_f, 0, row_p, replay, pre, true);
        std.mem.swap(u64, &ch.pre, &ch.pre_f);
        ch.start = replay;
        ch.n = n;
        // pos[first:]: a view, first * 8 bytes in (its alignment is the one the served kernels were specialized for). An odd
        // `first` leaves it off a 16-byte boundary, and the kit has no variant for some launches with such a view (a short
        // chunk's split attention: _sparse_attn_part with SPLITS > 1 and no row bases); the same positions copied, in the
        // stream's order, to a 16-byte boundary then: the kernels read the same values from an address they were captured for.
        if (pre > 0) {
            // the prepended rows' positions are not in pos0 (it starts at the pass's own start): [replay, replay + n)
            // written afresh to pos1 (16-byte aligned; host_pos is pageable, so the upload is staged before it returns)
            for (host_pos[0..n], 0..) |*p, i| p.* = @intCast(replay + i);
            try upload(e, ch.pos1, host_pos.ptr, n * 8);
            ch.pos = ch.pos1;
        } else if ((first * 8) % 16 != 0) { // (pos0 is 16-byte aligned: the view's alignment is first's)
            const src = ch.pos + first * 8;
            try e.d.check(e.d.api.cuMemcpyDtoDAsync_v2(ch.pos1, src, n * 8, e.s.handle), "cuMemcpyDtoDAsync");
            ch.pos = ch.pos1;
        } else ch.pos = ch.pos + first * 8;
    }
    try tailStash(e, ch, replay);
    return true;
}

/// DSpark tap j (_forward_k at a tap layer): a pending MoE gather posted into the streams first (hc_post, not fused),
/// then h.to(fp32).mean(1).to(bf16) into tap j's rows.
pub fn tap(e: *const Engine, ch: *Chunk, j: usize) !void {
    const c = e.c;
    try pendingPost(e, ch);
    try e.exact.hcMean4(e.s, ch.h, ch.taps + j * ch.cap * c.hidden * 2, c.hidden, ch.n, c.hidden);
}

/// Tap j's rows (bf16 [n, D]).
pub fn tapRows(e: *const Engine, ch: *const Chunk, j: usize) u64 {
    return ch.taps + j * ch.cap * e.c.hidden * 2;
}

/// The head on the chunk's last row (_forward_k without all_logits): the pending MoE post, collapse_norm of the row with
/// its pre, the head's columns (one row through the head's own group, fp32) and their gather: head_g holds the
/// prompt's logits, the ranks' columns in rank order.
pub fn head(e: *const Engine, ch: *Chunk) !void {
    const c = e.c;
    const n = ch.n;
    try pendingPost(e, ch);
    const last_h = ch.h + (n - 1) * c.hc * c.hidden * 2;
    const last_pre = ch.pre + (n - 1) * c.hc * 4;
    try tri_basic.collapseNorm(e.t, last_h, last_pre, e.w.norm, ch.head_x, c.eps, 1, c.hidden);
    const hl = e.w.head;
    try mmRows(e, ch, 1, hl, ch.head_x, c.hidden, ch.head_l, .fp32, hl.n);
    if (e.two) |t| return t.quarters(e, ch.head_l, ch.head_g, 1, t.hw, 4); // 2D: the vocabulary quarters, TP2's layout
    try e.comm.allGather(ch.head_l, ch.head_g, hl.n, .f32, e.s);
}

/// A layer's end: the MoE's gather is pending (the next layer's attention mixes post it) and the FFN's pre_out is the
/// next layer's pre (_forward_k's `pre, pre_f = pre_f, pre`).
pub fn endLayer(ch: *Chunk) void {
    ch.pending = true;
    std.mem.swap(u64, &ch.pre, &ch.pre_f);
}

