    pub fn drawRows(o: *const Ops, s: cuda.Stream, logits: u64, ld: usize, n: usize, rows: usize, table: u64, out: u64) !void {
        const f = o.draw_rows orelse return error.DeviceDrawOff;
        if (rows == 0 or n == 0) return;
        var a: cuda.Args = .{};
        a.add(logits);
        a.add(@as(u64, ld));
        a.add(@as(c_int, @intCast(n)));
        a.add(table);
        a.add(out);
        a.add(@as(c_int, @intFromBool(o.pdl)));
