    /// TF_DS_CONF_PACK: the confidence head's input conf_in fp32 [streams * steps, d + rank] in one launch
    /// (tf_ds_conf_pack_kernel; conf_pack.pack is its host reference): xc's first `steps` block rows of each stream
    /// (n a stream) widened, then the markov_embed rows of the tokens ids[i * (steps + 1) + s] widened and gathered
    /// into embs, an invalid id setting `invalid` and widening embs' existing row. Only called when the switch is on.
    pub fn confPack(o: *const Ops, s: cuda.Stream, xc: u64, embed: u64, vocab: usize, ids: u64, embs: u64, conf_in: u64, invalid: u64, streams: usize, n: usize, steps: usize, d: usize, rank: usize) !void {
        const f = o.conf_pack_fn orelse return error.ConfPackUnavailable;
        if (streams * steps == 0) return;
        var a: cuda.Args = .{};
        a.add(xc);
        a.add(embed);
        a.add(ids);
        a.add(embs);
        a.add(conf_in);
        a.add(invalid);
        a.add(@as(c_int, @intCast(n)));
        a.add(@as(c_int, @intCast(steps)));
        a.add(@as(c_int, @intCast(d)));
        a.add(@as(c_int, @intCast(rank)));
        a.add(@as(c_ulonglong, vocab));
        a.add(@as(c_int, @intFromBool(o.pdl)));
        try go(o, f, s, streams * steps, 256, &a);
    }

    pub fn gatherRows(o: *const Ops, s: cuda.Stream, src: u64, src_rows: usize, idx: u64, dst: u64, bytes: usize, rows: usize, invalid: u64) !void {
        if (rows == 0) return;
        var a: cuda.Args = .{};
        a.add(src);
        a.add(dst);
        a.add(idx);
        a.add(@as(u64, rows));
        a.add(@as(u64, src_rows));
        a.add(@as(u64, bytes));
        a.add(invalid);
        a.add(@as(c_int, @intFromBool(o.pdl)));
        try go(o, o.gather, s, rows, 256, &a);
    }
};

