extern "C" __global__ void tf_ds_clock_kernel(uint64_t* buf, uint32_t tag, uint32_t reset, uint32_t cap, int pdl) {
    pdl_enter(pdl);
    if (threadIdx.x == 0) {
        uint64_t t;
        asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t));
        const uint64_t i = reset ? 0 : buf[0];
        if (i < cap) {
