                        var want_p = try std.testing.allocator.alloc(u8, n * row_p);
                        defer std.testing.allocator.free(want_p);
                        var pos = try std.testing.allocator.alloc(i64, n);
                        defer std.testing.allocator.free(pos);
                        var want_pos = try std.testing.allocator.alloc(i64, n);
                        defer std.testing.allocator.free(want_pos);
                        // distinct bytes per ring slot and per fresh row, so a wrong source row cannot pass
                        for (0..window) |s| for (0..row_h) |j| tail_h[s * row_h + j] = @intCast((s * 31 + j * 7 + 1) & 0xff);
                        for (0..window) |s| for (0..row_p) |j| tail_p[s * row_p + j] = @intCast((s * 17 + j * 13 + 2) & 0xff);
                        for (0..n0) |r| for (0..row_h) |j| fresh_h[r * row_h + j] = @intCast((r * 53 + j * 11 + 3) & 0xff);
                        for (0..n0) |r| for (0..row_p) |j| fresh_p[r * row_p + j] = @intCast((r * 41 + j * 19 + 4) & 0xff);
                        @memset(out_h, 0xAA);
                        @memset(out_p, 0xAA);
                        Today.run(tail_h, tail_p, fresh_h, fresh_p, want_h, want_p, want_pos, row_h, row_p, window, pre, first, n, replay);
                        assemble(tail_h, tail_p, fresh_h, fresh_p, out_h, out_p, pos, row_h, row_p, window, pre, first, n, replay);
                        try std.testing.expectEqualSlices(u8, want_h, out_h);
                        try std.testing.expectEqualSlices(u8, want_p, out_p);
                        try std.testing.expectEqualSlices(i64, want_pos, pos);
                        cases += 1;
                    }
                }
            }
        }
    }
    try std.testing.expect(cases >= 150);
}

